export const SMAA_AREA = { width: 160, height: 560, channels: 2 } as const;
export const SMAA_SEARCH = { width: 64, height: 16, channels: 1 } as const;

const AREA_GZ =
	"";
const SEARCH_GZ =
	"H4sIAAAAAAAC//v3j6G+noHhH4SCAiATxANT/+phQljBPwr1Uwr+DXH3UwqQnYpVsB6/+ynVP9LdP9QBAFM0QncABAAA";

async function unzip(base64: string): Promise<Uint8Array> {
	const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
	const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
	return new Uint8Array(await new Response(stream).arrayBuffer());
}

/** The two tables' texels, row by row from the top, as the reference lays them out. */
export async function smaaTables(): Promise<{ area: Uint8Array; search: Uint8Array }> {
	const [area, search] = await Promise.all([unzip(AREA_GZ), unzip(SEARCH_GZ)]);
	return { area, search };
}
